INSERT OR REPLACE INTO LocalizedText(Language,Tag,Text) VALUES ('zh_Hans_CN','LOC_PROJECT_SPC_CLAIM_RESEARCH_NAME','认定科研专业'),('zh_Hans_CN','LOC_PROJECT_SPC_CLAIM_RESEARCH_DESCRIPTION','开启后将作为唯一当前生产目标，连续占用 1 个完整回合。项目完成后，本城将确立「科研」专业身份并获得 1 级专业潜力（其它专业认定项目将随之移除）。项目开启前未分配的生产力及项目期间产生的生产力均不会结转至后续目标；中途保存或读档会继续正常计时，但若在队列中改选其它项目，再次开启时需重新计时。');
INSERT OR REPLACE INTO LocalizedText(Language,Tag,Text) VALUES ('en_US','LOC_PROJECT_SPC_CLAIM_RESEARCH_NAME','认定科研专业'),('en_US','LOC_PROJECT_SPC_CLAIM_RESEARCH_DESCRIPTION','选为唯一当前目标，连续占用一个完整回合。完成后认领科研专业，潜力为1，其它认领项目撤下。已有未分配生产和项目期间生产不转入后续目标；保存读档继续计时，改选后需重新开始。');
